.reports-intro{padding:8px 2px 14px}.reports-intro h2{margin:4px 0;font-size:30px}.reports-intro p{margin:0}.report-layout{grid-template-columns:minmax(0,2fr) minmax(240px,1fr)}.report-layout fieldset{border:1px solid var(--line);border-radius:14px;padding:14px;margin:0 0 14px}.report-columns{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:6px}.report-column{display:flex;align-items:center;gap:8px;padding:8px;border-radius:9px;background:var(--canvas)}.report-column input{width:16px;margin:0}.save-report{border-top:1px solid var(--line);margin-top:18px;padding-top:14px}.save-line{display:flex;gap:8px}.save-line input{margin:5px 0}.saved-reports ul{padding:0;list-style:none}.saved-reports li{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:9px 0;border-bottom:1px solid var(--line)}.saved-reports li:last-child{border:0}.saved-reports li form{margin:0}.saved-reports .btn{padding:6px 9px;font-size:11px}@media(max-width:760px){.report-layout{grid-template-columns:1fr}.save-line{flex-direction:column}}
